3584	pub fn scrollCallback(
3585	    self: *Surface,
3586	    xoff: f64,
3587	    yoff: f64,
3588	    scroll_mods: input.ScrollMods,
3589	) !void {
3590	    // log.info("SCROLL: xoff={} yoff={} mods={}", .{ xoff, yoff, scroll_mods });
3591	
3592	    // Crash metadata in case we crash in here
3593	    crash.sentry.thread_state = self.crashThreadState();
3594	    defer crash.sentry.thread_state = null;
3595	
3596	    // Always show the mouse again if it is hidden
3597	    if (self.mouse.hidden) self.showMouse();
3598	
3599	    const y: ScrollAmount = if (yoff == 0) .{} else y: {
3600	        // We use cell_size to determine if we have accumulated enough to trigger a scroll
3601	        const cell_size: f64 = @floatFromInt(self.size.cell.height);
3602	
3603	        // If we have precision scroll, yoff is the number of pixels to scroll. In non-precision
3604	        // scroll, yoff is the number of wheel ticks. Some mice are capable of reporting fractional
3605	        // wheel ticks, which don't necessarily get reported as precision scrolls. We normalize all
3606	        // scroll events to pixels by multiplying the wheel tick value and the cell size. This means
3607	        // that a wheel tick of 1 results in single scroll event.
3608	        const yoff_adjusted: f64 = if (scroll_mods.precision)
3609	            yoff * self.config.mouse_scroll_multiplier.precision
3610	        else yoff_adjusted: {
3611	            if (comptime builtin.target.os.tag.isDarwin()) {
3612	                // Round out the yoff to an absolute minimum of 1. macos tries to
3613	                // simulate precision scrolling with non precision events by
3614	                // ramping up the magnitude of the offsets as it detects faster
3615	                // scrolling. Single click (very slow) scrolls are reported with a
3616	                // magnitude of 0.1 which would normally require a few clicks
3617	                // before we register an actual scroll event (depending on cell
3618	                // height and the mouse_scroll_multiplier setting).
3619	                const yoff_max: f64 = if (yoff > 0)
3620	                    @max(yoff, 1)
3621	                else
3622	                    @min(yoff, -1);
3623	
3624	                break :yoff_adjusted yoff_max * cell_size * self.config.mouse_scroll_multiplier.discrete;
3625	            } else {
3626	                break :yoff_adjusted yoff * cell_size * self.config.mouse_scroll_multiplier.discrete;
3627	            }
3628	        };
3629	
3630	        // Add our previously saved pending amount to the offset to get the
3631	        // new offset value. The signs of the pending and yoff should match
3632	        // so that we move further away from zero, but we don't assert
3633	        // this because in theory a user could scroll in the opposite
3634	        // direction and undo a pending scroll.
3635	        const poff: f64 = self.mouse.pending_scroll_y + yoff_adjusted;
3636	
3637	        // If the new offset is less than a single unit of scroll, we save
3638	        // the new pending value and do not scroll yet.
3639	        if (@abs(poff) < cell_size) {
3640	            self.mouse.pending_scroll_y = poff;
3641	            break :y .{};
3642	        }
3643	
3644	        // We scroll by the number of rows in the offset and save the remainder
3645	        const amount = poff / cell_size;
3646	        assert(@abs(amount) >= 1);
3647	        self.mouse.pending_scroll_y = poff - (amount * cell_size);
3648	
3649	        // Round towards zero.
3650	        const delta: isize = @intFromFloat(@trunc(amount));
3651	        assert(@abs(delta) >= 1);
3652	
3653	        break :y .{ .delta = delta };
3654	    };
3655	
3656	    // For detailed comments see the y calculation above.
3657	    const x: ScrollAmount = if (xoff == 0) .{} else x: {
3658	        if (!scroll_mods.precision) {
