3660	            break :x .{ .delta = x_delta_isize };
3661	        }
3662	
3663	        const poff: f64 = self.mouse.pending_scroll_x + xoff;
3664	        const cell_size: f64 = @floatFromInt(self.size.cell.width);
3665	        if (@abs(poff) < cell_size) {
