3668	        }
3669	
3670	        const amount = poff / cell_size;
3671	        assert(@abs(amount) >= 1);
3672	        self.mouse.pending_scroll_x = poff - (amount * cell_size);
3673	        const delta: isize = @intFromFloat(@trunc(amount));
3674	        assert(@abs(delta) >= 1);
3675	        break :x .{ .delta = delta };
3676	    };
3677	
3678	    // log.info("SCROLL: delta_y={} delta_x={}", .{ y.delta, x.delta });
3679	
3680	    {
3681	        self.renderer_state.mutex.lockUncancelable(global.io());
3682	        defer self.renderer_state.mutex.unlock(global.io());
3683	
3684	        // If we have an active mouse reporting mode, clear the selection.
3685	        // The selection can occur if the user uses the shift mod key to
3686	        // override mouse grabbing from the window.
3687	        if (self.isMouseReporting()) {
3688	            try self.setSelection(null);
3689	        }
3690	
3691	        // If we're in alternate screen with alternate scroll enabled, then
3692	        // we convert to cursor keys. This only happens if we're:
3693	        // (1) alt screen (2) no explicit mouse reporting and (3) alt
3694	        // scroll mode enabled.
3695	        if (self.io.terminal.screens.active_key == .alternate and
3696	            self.io.terminal.flags.mouse_event == .none and
3697	            self.io.terminal.modes.get(.mouse_alternate_scroll))
3698	        {
3699	            if (y.delta != 0) {
3700	                // When we send mouse events as cursor keys we always
3701	                // clear the selection.
3702	                try self.setSelection(null);
