3704	                const seq = if (self.io.terminal.modes.get(.cursor_keys)) seq: {
3705	                    // cursor key: application mode
3706	                    break :seq switch (y.direction()) {
3707	                        .up_right => "\x1bOA",
3708	                        .down_left => "\x1bOB",
3709	                    };
3710	                } else seq: {
3711	                    // cursor key: normal mode
