4683	    // Crash metadata in case we crash in here
4684	    crash.sentry.thread_state = self.crashThreadState();
4685	    defer crash.sentry.thread_state = null;
4686	
4687	    // log.debug("cursor pos x={} y={} mods={?}", .{ pos.x, pos.y, mods });
4688	
4689	    // If the position is negative, it is outside our viewport and
4690	    // we need to clear any hover states.
4691	    if (pos.x < 0 or pos.y < 0) {
4692	        // Reset our hyperlink state
4693	        self.mouse.link_point = null;
4694	        if (self.mouse.over_link) {
4695	            self.mouse.over_link = false;
4696	            _ = try self.rt_app.performAction(
4697	                .{ .surface = self },
4698	                .mouse_shape,
4699	                self.io.terminal.mouse_shape,
4700	            );
4701	            _ = try self.rt_app.performAction(
4702	                .{ .surface = self },
4703	                .mouse_over_link,
4704	                .{ .url = "" },
4705	            );
