4707	        }
4708	
4709	        self.renderer_state.mutex.lockUncancelable(global.io());
4710	        defer self.renderer_state.mutex.unlock(global.io());
4711	
4712	        // No mouse point so we don't highlight links
4713	        self.renderer_state.mouse.point = null;
4714	
4715	        // Mark the link's row as dirty, but continue with updating the
4716	        // mouse state below so we can scroll when our position is negative.
4717	        self.renderer_state.terminal.screens.active.dirty.hyperlink_hover = true;
4718	    }
4719	
4720	    // Always show the mouse again if it is hidden
4721	    if (self.mouse.hidden) self.showMouse();
4722	
4723	    // Update our modifiers if they changed
4724	    if (mods) |v| self.modsChanged(v);
4725	
4726	    // The mouse position in the viewport
4727	    const pos_vp = self.posToViewport(pos.x, pos.y);
4728	
4729	    // We always reset the over link status because it will be reprocessed
4730	    // below. But we need the old value to know if we need to undo mouse
4731	    // shape changes.
4732	    const over_link = self.mouse.over_link;
4733	    self.mouse.over_link = false;
4734	
4735	    // We are reading/writing state for the remainder
4736	    self.renderer_state.mutex.lockUncancelable(global.io());
4737	    defer self.renderer_state.mutex.unlock(global.io());
4738	
4739	    // Update our mouse state. We set this to null initially because we only
4740	    // want to set it when we're not selecting or doing any other mouse
4741	    // event.
4742	    self.renderer_state.mouse.point = null;
4743	
4744	    // If we have an inspector, we need to always record position information
4745	    if (self.inspector) |insp| {
4746	        insp.mouse.last_xpos = pos.x;
4747	        insp.mouse.last_ypos = pos.y;
4748	
4749	        const screen: *terminal.Screen = self.renderer_state.terminal.screens.active;
4750	        insp.mouse.last_point = screen.pages.pin(.{ .viewport = .{
4751	            .x = pos_vp.x,
4752	            .y = pos_vp.y,
4753	        } });
4754	        try self.queueRender();
4755	    }
4756	
4757	    // Handle link hovering
4758	    // We refresh links when
4759	    // 1. we were previously over a link
4760	    // OR
4761	    // 2. the cursor position has changed (either we have no previous state, or the state has
4762	    //    changed)
4763	    // AND
4764	    // 1. mouse reporting is off
4765	    // OR
4766	    // 2. mouse reporting is on and we are not reporting shift to the terminal
4767	    if ((over_link or
4768	        self.mouse.link_point == null or
4769	        (self.mouse.link_point != null and !self.mouse.link_point.?.eql(pos_vp))) and
4770	        (self.io.terminal.flags.mouse_event == .none or
4771	            (self.mouse.mods.shift and !self.mouseShiftCapture(false))))
4772	    {
4773	        // If we were previously over a link, we always update. We do this so that if the text
4774	        // changed underneath us, even if the mouse didn't move, we update the URL hints and state
4775	        try self.mouseRefreshLinks(pos, pos_vp, over_link);
4776	    }
4777	
4778	    // Do a mouse report
4779	    if (self.isMouseReporting()) report: {
4780	        // Shift overrides mouse "grabbing" in the window, taken from Kitty.
4781	        // This only applies if there is a mouse button pressed so that
4782	        // movement reports are not affected.
4783	        if (self.mouse.mods.shift and !self.mouseShiftCapture(false)) {
4784	            for (self.mouse.click_state) |state| {
4785	                if (state != .release) break :report;

3740	                const pos = try self.rt_surface.getCursorPos();
3741	                self.mouseReport(switch (x.direction()) {
3742	                    .up_right => .six,
3743	                    .down_left => .seven,
3744	                }, .press, self.mouse.mods, pos);
3745	            }
3746	
3747	            // If mouse reporting is on, we do not want to scroll the
3748	            // viewport.
3749	            return;
3750	        }
3751	
3752	        if (y.delta != 0) {
3753	            // Modify our viewport, this requires a lock since it affects
3754	            // rendering. We have to switch signs here because our delta
3755	            // is negative down but our viewport is positive down.
3756	            self.io.terminal.scrollViewport(.{ .delta = y.delta * -1 });
3757	        }
3758	    }
3759	
3760	    try self.queueRender();
