4822	        const screen: *terminal.Screen = t.screens.active;
4823	        const pin = screen.pages.pin(.{
4824	            .viewport = .{
4825	                .x = pos_vp.x,
4826	                .y = pos_vp.y,
4827	            },
4828	        }) orelse {
