6010	/// Call this to complete a clipboard request sent to apprt. This should
6011	/// only be called once for each request.
6012	///
6013	/// If `complete.confirmed` is false then this may return either an
6014	/// UnsafePaste or UnauthorizedPaste error, depending on the type of
6015	/// clipboard request. The request state remains alive in that case so
6016	/// the apprt can run its confirmation flow.
6017	pub fn completeClipboardRequest(
6018	    self: *Surface,
6019	    req: apprt.ClipboardRequest,
6020	    complete: CompleteClipboard,
6021	) !void {
6022	    switch (req) {
6023	        .paste => try self.completeClipboardPaste(
6024	            clipboardTextContent(complete.contents) orelse "",
6025	            complete.confirmed,
6026	        ),
6027	
6028	        .list => |clipboard| if (!try self.completeClipboardPasteEvent(
6029	            clipboard,
6030	            complete.available,
6031	        )) {
6032	            log.debug("mode 5522 paste event was not written", .{});
6033	        },
6034	
6035	        .osc_52_read => |clipboard| try self.completeClipboardReadOSC52(
6036	            clipboardTextContent(complete.contents) orelse "",
6037	            clipboard,
6038	            complete.confirmed,
6039	        ),
6040	
6041	        .osc_52_write => |clipboard| {
6042	            // The write API wants sentinel-terminated data; the write
6043	            // text round-tripped through the apprt confirmation flow as
6044	            // a plain representation.
6045	            const data = try self.alloc.dupeSentinel(
6046	                u8,
6047	                clipboardTextContent(complete.contents) orelse "",
6048	                0,
6049	            );
6050	            defer self.alloc.free(data);
6051	            try self.rt_surface.setClipboard(clipboard, &.{.{
6052	                .mime = "text/plain",
6053	                .data = data,
6054	            }}, !complete.confirmed);
6055	        },
6056	
6057	        .kitty_read => |kitty| {
6058	            // If we need confirmation we return an error without
6059	            // consuming the request state; the apprt keeps it alive
6060	            // for the confirmation flow. A session grant carried by
6061	            // the request skips the prompt, and a request with no
6062	            // data types is exempt from prompting entirely; see
6063	            // readPromptExempt.
6064	            if (self.config.clipboard_read == .ask and
6065	                !complete.confirmed and
6066	                !kitty.granted and
6067	                !terminal.kitty.clipboard.readPromptExempt(kitty.mimes.len))
6068	            {
6069	                return error.UnauthorizedPaste;
6070	            }
6071	
6072	            // Past the confirmation check the request is consumed:
6073	            // every path from here, including errors, must destroy it.
6074	            defer kitty.destroy();
